mapper.select:

SELECT DISTINCT u.user_id, u.username, u.display_name, u.status, u.lock_version, u.created_at, u.updated_at
FROM user_account u

  JOIN user_role_assignment ura ON ura.tenant_id = u.tenant_id AND ura.user_id = u.user_id
  JOIN role r ON r.tenant_id = ura.tenant_id AND r.role_id = ura.role_id

WHERE u.tenant_id = #{tenantId}
AND u.status = #{status}
AND ura.state = 'GRANTED' AND r.status = 'ACTIVE' AND r.role_code = #{roleCode}

  AND (  #{lastName}
    OR ( = #{lastName}
      AND u.user_id  #{lastId}))

ORDER BY  , u.user_id 
LIMIT #{limit}
